'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlantr = require( './../lib/main.js' );


// VARIABLES //

var sizes = [ 10, 100 ];
var norms = [ 'max', 'one', 'infinity', 'frobenius' ];
var i;
var j;


// FUNCTIONS //

/**
* Creates a matrix norm benchmark.
*
* @private
* @param {PositiveInteger} N - matrix dimension
* @param {string} norm - norm type
* @returns {Function} benchmark function
*/
function createBenchmark( N, norm ) {
	var work;
	var A;
	var i;

	A = new Float64Array( N*N );
	work = new Float64Array( N );
	for ( i = 0; i < A.length; i++ ) {
		A[i] = (i%19) - 9;
	}
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = dlantr( 'row-major', norm, 'upper', 'non-unit', N, N, A, N, work );
			if ( isnan( out ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( out ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

for ( i = 0; i < sizes.length; i++ ) {
	for ( j = 0; j < norms.length; j++ ) {
		bench( format( '%s::norm=%s,N=%d', pkg, norms[j], sizes[i] ), createBenchmark( sizes[i], norms[j] ) );
	}
}
